import { useState } from "react";

import { SectionPage, Specimen } from "../kit.js";

import { IconOrganisation } from "../../icons/generated/icons.js";

import { PopoutWindow, Window, WindowManagerProvider, createWindowManager, registerWindowKind } from "../../windows/index.js";

function SampleWindowBody() {
    return (<Window.Body>
      <p>Fictional exhibition notes.</p>
    </Window.Body>);
}

function makeWindowDemo() {
    registerWindowKind({
        kind: "docs.notes",
        icon: IconOrganisation,
        title: () => "Exhibition notes",
        load: async () => ({ default: SampleWindowBody }),
    });
    const manager = createWindowManager({ storageKey: null, channelName: null });
    const id = manager.open({ kind: "docs.notes", params: {} });
    return { manager, id };
}

export default function PopoutWindowExample() {
    const [{ manager, id }] = useState(makeWindowDemo);
    return (<SectionPage>
      <Specimen title="Standalone window host" description="A real application renders this component on its pop-out route with the same manager storage/channel as the workspace." layout="stack">
        <WindowManagerProvider manager={manager}>
          <div className="relative h-90 w-full">
            <PopoutWindow id={id}/>
          </div>
        </WindowManagerProvider>
      </Specimen>
    </SectionPage>);
}
